REPLACE INTO `clob_datatype_storage` (`id`,`uuid`,`value`) VALUES (1012,'89752c97-24dc-44c2-8f40-ba9b02b71417','{\"name\":\"HIV Care and Treatment Transfer\",\"uuid\":\"4963a72c-4b0d-467a-a1d0-64d981ff585c\",\"processor\":\"EncounterFormProcessor\",\"encounterType\":\"7b68d557-85ef-4fc8-b767-4fa4f5eb5c23\",\"referencedForms\":[],\"version\":\"2018\",\"published\":true,\"retired\":false,\"pages\":[{\"label\":\"Facility/Visit Date\",\"sections\":[{\"label\":\"Transfer Details\",\"isExpanded\":\"true\",\"questions\":[{\"label\":\"Visit Date\",\"type\":\"encounterDatetime\",\"required\":true,\"id\":\"visitDate\",\"datePickerFormat\":\"calendar\",\"questionOptions\":{\"rendering\":\"date\",\"concept\":\"6bcaf85b-8504-4c7f-b510-a50436236b80\"},\"validators\":[{\"type\":\"date\",\"allowFutureDates\":\"false\"}]},{\"label\":\"Transferring From\",\"type\":\"control\",\"id\":\"facilityName\",\"questionOptions\":{\"rendering\":\"text\",\"calculate\":{\"calculateExpression\":\"resolve(getSystemSetting(\'Facility_Name\')).then(a => resolve(getSystemSetting(\'partner_reporting_lga_code\')).then(lgaCode => resolve(lookupAddressHierarchyName(lgaCode, \'3\')).then(lgaName => resolve(getSystemSetting(\'partner_reporting_state\')).then(stateCode => resolve(lookupAddressHierarchyName(stateCode, \'2\')).then(stateName => a + \' , \' + lgaName + \' , \' + stateName)))))\"}},\"readonly\":\"true\"},{\"label\":\"Transferring To\",\"type\":\"obs\",\"id\":\"facilityTransferredTo\",\"questionOptions\":{\"rendering\":\"text\",\"concept\":\"159495AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"}},{\"label\":\"State\",\"type\":\"obs\",\"id\":\"facilityTransferredstate\",\"questionOptions\":{\"rendering\":\"ui-select-extended\",\"concept\":\"32df263e-24bc-4655-83e0-e2bdfbb2b68d\",\"datasource\":{\"name\":\"nigeriaStates\",\"config\":{}}}},{\"label\":\"LGA\",\"type\":\"obs\",\"id\":\"facilityTransferredLga\",\"questionOptions\":{\"rendering\":\"ui-select-extended\",\"concept\":\"738f7aaf-db3a-4b37-901a-1a673d3f881