esolve(getProgramEnrollmentDate(patient.id, \'9083deaa-f37f-44b3-9046-b87b134711a1\'))\"}},\"readonly\":true},{\"label\":\"Date Commenced on ART\",\"type\":\"control\",\"id\":\"dateCommencedArt\",\"questionOptions\":{\"rendering\":\"date\",\"calculate\":{\"calculateExpression\":\"resolve(api.getLatestObs(patient.id, \'159599AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\')).then(obs => obs?.effectiveDateTime ? new Date(obs.effectiveDateTime) : null)\"}},\"readonly\":true},{\"label\":\"Current WHO clinical stage\",\"type\":\"control\",\"id\":\"currentWhoStage\",\"questionOptions\":{\"rendering\":\"text\",\"calculate\":{\"calculateExpression\":\"resolve(api.getLatestObs(patient.id, \'5356AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\')).then(obs => obs?.valueCodeableConcept?.coding?.[0]?.display ?? \'\')\"}},\"readonly\":true},{\"label\":\"Baseline CD4 Count (cells/mm3)\",\"type\":\"control\",\"id\":\"baselineCd4\",\"questionOptions\":{\"rendering\":\"number\",\"calculate\":{\"calculateExpression\":\"resolve(getEarliestObs(patient.id, \'5497AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\')).then(obs => obs?.valueQuantity?.value ?? null)\"}},\"readonly\":true},{\"label\":\"Current CD4 Count (cells/mm3)\",\"type\":\"control\",\"id\":\"currentCd4\",\"questionOptions\":{\"rendering\":\"number\",\"calculate\":{\"calculateExpression\":\"resolve(api.getLatestObs(patient.id, \'5497AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\')).then(obs => obs?.valueQuantity?.value ?? null)\"}},\"readonly\":true},{\"label\":\"Current Viral Load (copies/ml)\",\"type\":\"control\",\"id\":\"currentViralLoad\",\"questionOptions\":{\"rendering\":\"number\",\"calculate\":{\"calculateExpression\":\"resolve(api.getLatestObs(patient.id, \'856AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\')).then(obs => obs?.valueQuantity?.value ?? null)\"}},\"readonly\":true},{\"label\":\"Height (m/cm)\",\"type\":\"control\",\"id\":\"latestHeight\",\"questionOptions\":{\"rendering\":\"number\",\"calculate\":{\"calculateExpression\":\"resolve(api.getLatestObs(patient.id, \'5090AAAAAA