REPLACE INTO `clob_datatype_storage` (`id`,`uuid`,`value`) VALUES (1019,'eaa255f7-7f1e-4140-8c12-17f417553360','{\"name\":\"HIV Tracking Register\",\"description\":\"New tools combined and rename: Client Tracking Register, Client Tracking & Discontinuation Form\",\"version\":\"2026.03.27\",\"published\":true,\"retired\":false,\"processor\":\"EncounterFormProcessor\",\"encounter\":\"Client Tracking and Termination\",\"referencedForms\":[],\"uuid\":\"5fbc99be-9aeb-4f94-85b0-b2fae88a0ced\",\"pages\":[{\"label\":\"HIV Tracking Register\",\"sections\":[{\"label\":\"Client Records\",\"isExpanded\":\"true\",\"questions\":[{\"label\":\"Address / Phone No.\",\"type\":\"control\",\"id\":\"historical_data_snapshot\",\"questionOptions\":{\"rendering\":\"text\",\"calculate\":{\"calculateExpression\":\"\'Address: \' + (patient.address?.[0] ? [patient.address[0].address1, patient.address[0].address2, patient.address[0].address3, patient.address[0].address4, patient.address[0].address5, patient.address[0].address6, patient.address[0].city, patient.address[0].countyDistrict, patient.address[0].state, patient.address[0].postalCode, patient.address[0].country].filter(Boolean).join(\', \') : \'No Address Data\') + \'  *  Phone No.: \' + (patient.telecom?.[0] ? patient.telecom[0].value : \'No Phone Data\') \"}},\"readonly\":true},{\"label\":\"ART Start Date\",\"type\":\"control\",\"id\":\"_aRT_start_date_\",\"questionOptions\":{\"rendering\":\"date\",\"calculate\":{\"calculateExpression\":\"resolve(api.getLatestObs(patient.id, \'159599AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\')).then(obs => obs?.valueDateTime ? new Date(obs.valueDateTime) : null)\"}},\"readonly\":true},{\"label\":\"Current ART Regimen\",\"type\":\"control\",\"id\":\"current_art_regimen\",\"questionOptions\":{\"rendering\":\"text\",\"calculate\":{\"calculateExpression\":\"resolve(api.getLatestObs(patient.id, \'164506AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\')).then(obs => obs?.valueCodeableConcept?.coding?.[0]?.display ?? \'No Regimen Recor