'1AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\' ? 1 : 0))\"}}}]},{\"label\":\"(B) Personal HIV Risk Assessment (Last 3 months)\",\"isExpanded\":\"true\",\"questions\":[{\"label\":\"Ever had sexual intercourse:\",\"type\":\"obs\",\"id\":\"sexual_intercourse\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"d67272b2-3846-408a-8faa-c5a50ab3ff1c\",\"answers\":[{\"concept\":\"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"No\"},{\"concept\":\"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Yes\"}]}},{\"label\":\"More than 1 sex partner:\",\"type\":\"obs\",\"id\":\"moresex_partner\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"321f1f62-6915-4504-956b-af3f1a715017\",\"answers\":[{\"concept\":\"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"No\"},{\"concept\":\"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Yes\"}]}},{\"label\":\"Unprotected Vaginal Sex:\",\"type\":\"obs\",\"id\":\"unprotected_Vaginal_Sex\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"159218AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"answers\":[{\"concept\":\"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"No\"},{\"concept\":\"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Yes\"}]}},{\"label\":\"Unprotected Anal Sex:\",\"type\":\"obs\",\"id\":\"unprotected_anal_sex\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"163278AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"answers\":[{\"concept\":\"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"No\"},{\"concept\":\"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Yes\"}]}},{\"label\":\"Blood transfusion in last 3 months:\",\"type\":\"obs\",\"id\":\"blood_transfusion\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"1063AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"answers\":[{\"concept\":\"2AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"No\"},{\"concept\":\"1AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Yes\"}]}},{\"label\":\"Sex under the influence of drugs or alcohol:\",\"type\":\"obs\",\"id\":\"sex_