AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Yes\"}]}},{\"label\":\"TB Screening Score (Sum of the 4 answers above):\",\"type\":\"obs\",\"id\":\"tb_screening_score\",\"readonly\":true,\"questionOptions\":{\"rendering\":\"number\",\"concept\":\"2ca1be00-bc68-42b3-9e76-79cbdd26c08f\",\"min\":\"0\",\"max\":\"4\",\"calculate\":{\"calculateExpression\":\"Math.round((Current_Cough === \'1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\' ? 1 : 0) + (Weight_Loss === \'1AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\' ? 1 : 0) + (Fever === \'1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\' ? 1 : 0) + (Night_sweats === \'1AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\' ? 1 : 0))\"}}},{\"label\":\"⚠️ TB Score ≥1: Test for Xpert MTB RIF or refer to TB service.\",\"type\":\"control\",\"id\":\"tb_referral_guidance\",\"readonly\":true,\"hide\":{\"hideWhenExpression\":\"!(Math.round((Current_Cough === \'1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\' ? 1 : 0) + (Weight_Loss === \'1AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\' ? 1 : 0) + (Fever === \'1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\' ? 1 : 0) + (Night_sweats === \'1AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\' ? 1 : 0)) >= 1)\"}}]},{\"label\":\"(C) Syndromic STI Screening\",\"isExpanded\":\"true\",\"questions\":[{\"label\":\"Female: Complaints of vaginal discharge or burning when urinating?\",\"type\":\"obs\",\"id\":\"Complaints_of_vaginal_discharge\",\"hide\":{\"hideWhenExpression\":\"sex !== \'F\'\"},\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"2cabc6b8-ec7d-463c-9e47-d3de7599feca\",\"answers\":[{\"concept\":\"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"No\"},{\"concept\":\"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Yes\"}]}},{\"label\":\"Female: Complaints of lower abdominal pains with or without vaginal discharge?\",\"type\":\"obs\",\"id\":\"Complaints_of_lower_abdominal_pains\",\"hide\":{\"hideWhenExpression\":\"sex !== \'F\'\"},\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"4ea92538-9196-4d11-ae72-a61c41260e37\",\"answers\":[{\"concept\":\"1